{
  "format_version": 3,
  "flavours": {
    "candidate": {
      "id_prefix": "CAND-",
      "body": "required",
      "description": "Fixture candidate under verification",
      "use_when": [
        "Fixture query root"
      ],
      "avoid_when": [],
      "distinguish_from": {},
      "fields": {
        "status": {
          "type": "enum",
          "values": [
            "draft",
            "accepted",
            "retired"
          ],
          "required": true
        },
        "likelihood": {
          "type": "integer"
        },
        "consequence": {
          "type": "integer"
        }
      }
    },
    "verification": {
      "id_prefix": "VER-",
      "body": "required",
      "description": "Fixture verification required by a candidate",
      "use_when": [
        "Fixture required fact subject"
      ],
      "avoid_when": [],
      "distinguish_from": {},
      "fields": {
        "status": {
          "type": "enum",
          "values": [
            "draft",
            "accepted",
            "retired"
          ],
          "required": true
        }
      }
    }
  },
  "relations": {
    "requires_verification": {
      "description": "Fixture candidate-to-verification requirement",
      "source": [
        "candidate"
      ],
      "target": [
        "verification"
      ],
      "inverse": "required_by"
    }
  }
}

{
  "format_version": 5,
  "definitions": [
    {
      "id": "urn:fixture:facts:verifications",
      "required_fact_sources": [
        "documents",
        "external"
      ],
      "root_flavours": [
        "candidate"
      ],
      "columns": {
        "verification": {
          "type": "item",
          "flavours": [
            "verification"
          ]
        },
        "candidate": {
          "type": "text"
        },
        "context": {
          "type": "text"
        },
        "state": {
          "type": "text"
        }
      },
      "parameters": {
        "candidate": {
          "type": "text",
          "required": true
        },
        "context": {
          "type": "text",
          "required": true
        }
      },
      "external_facts": [
        {
          "input": "reported",
          "keys": [
            "verification",
            "candidate",
            "context"
          ],
          "fields": {
            "state": "state"
          },
          "missing": {
            "state": {
              "type": "text",
              "value": "missing"
            }
          }
        }
      ],
      "select": "PREFIX r: <urn:mara:relation:>\nPREFIX f: <urn:mara:field:>\nSELECT ?root ?verification ?candidate ?context ?edge WHERE {\n  ?root r:requires_verification ?verification .\n  ?edge <urn:mara:query:source> ?root ;\n        <urn:mara:query:target> ?verification ;\n        <urn:mara:query:relation> r:requires_verification .\n  ?verification f:status ?vstatus .\n  FILTER(sameTerm(?vstatus, \"accepted\"))\n}",
      "support_columns": [
        "edge"
      ]
    },
    {
      "id": "urn:fixture:facts:validation",
      "required_fact_sources": [
        "documents",
        "external"
      ],
      "root_flavours": [
        "candidate"
      ],
      "columns": {
        "verification": {
          "type": "item",
          "flavours": [
            "verification"
          ]
        },
        "candidate": {
          "type": "text"
        },
        "context": {
          "type": "text"
        },
        "state": {
          "type": "text"
        },
        "members": {
          "type": "integer"
        }
      },
      "parameters": {
        "candidate": {
          "type": "text",
          "required": true
        },
        "context": {
          "type": "text",
          "required": true
        }
      },
      "external_facts": [
        {
          "input": "reported",
          "keys": [
            "verification",
            "candidate",
            "context"
          ],
          "fields": {
            "state": "state"
          },
          "missing": {
            "state": {
              "type": "text",
              "value": "missing"
            }
          }
        }
      ],
      "select": "PREFIX r: <urn:mara:relation:>\nPREFIX f: <urn:mara:field:>\nSELECT ?root ?verification ?candidate ?context ?edge WHERE {\n  ?root r:requires_verification ?verification .\n  ?edge <urn:mara:query:source> ?root ;\n        <urn:mara:query:target> ?verification ;\n        <urn:mara:query:relation> r:requires_verification .\n  ?verification f:status ?vstatus .\n  FILTER(sameTerm(?vstatus, \"accepted\"))\n}",
      "aggregate": {
        "group_by": [
          "candidate",
          "context"
        ],
        "rank": "state",
        "precedence": [
          {
            "type": "text",
            "value": "error"
          },
          {
            "type": "text",
            "value": "fail"
          },
          {
            "type": "text",
            "value": "missing"
          },
          {
            "type": "text",
            "value": "inconclusive"
          },
          {
            "type": "text",
            "value": "pending"
          },
          {
            "type": "text",
            "value": "pass"
          }
        ],
        "retain": [
          "verification"
        ],
        "count": "members",
        "empty": {
          "type": "text",
          "value": "missing"
        }
      },
      "support_columns": [
        "edge"
      ]
    },
    {
      "id": "urn:fixture:facts:risk",
      "required_fact_sources": [
        "documents"
      ],
      "root_flavours": [
        "candidate"
      ],
      "columns": {
        "likelihood": {
          "type": "integer"
        },
        "consequence": {
          "type": "integer"
        },
        "score": {
          "type": "integer"
        },
        "band": {
          "type": "text"
        }
      },
      "lookups": [
        {
          "mapping": "risk_matrix",
          "keys": [
            "likelihood",
            "consequence"
          ],
          "output": "score"
        },
        {
          "mapping": "risk_band",
          "keys": [
            "score"
          ],
          "output": "band"
        }
      ],
      "select": "PREFIX f: <urn:mara:field:>\nSELECT ?root ?likelihood ?consequence WHERE {\n  ?root f:likelihood ?likelihood ; f:consequence ?consequence\n}"
    },
    {
      "id": "urn:fixture:facts:composed",
      "required_fact_sources": [
        "documents"
      ],
      "root_flavours": [
        "candidate"
      ],
      "columns": {
        "verification": {
          "type": "item",
          "flavours": [
            "verification"
          ]
        },
        "selected_candidate": {
          "type": "text"
        },
        "selected_context": {
          "type": "text"
        },
        "state": {
          "type": "text"
        }
      },
      "parameters": {
        "candidate": {
          "type": "text",
          "required": true
        },
        "context": {
          "type": "text",
          "required": true
        }
      },
      "facts_columns": [
        "child_facts"
      ],
      "dependencies": [
        {
          "name": "child",
          "definition": "urn:fixture:facts:verifications",
          "root": "root",
          "parameters": {
            "candidate": "candidate",
            "context": "context"
          },
          "projections": {
            "columns": {
              "verification": "verification",
              "candidate": "candidate",
              "context": "context",
              "state": "state"
            },
            "facts": "child_facts"
          }
        }
      ],
      "select": "SELECT ?root ?verification ?selected_candidate ?selected_context ?state ?child_facts WHERE {\n  ?root <urn:mara:query:input:child> ?row .\n  ?row <urn:mara:query:column:child:verification> ?verification ;\n       <urn:mara:query:column:child:candidate> ?selected_candidate ;\n       <urn:mara:query:column:child:context> ?selected_context ;\n       <urn:mara:query:column:child:state> ?state ;\n       <urn:mara:query:column:child:child_facts> ?child_facts .\n}"
    }
  ]
}
